{
  "name": "opencode-console",
  "version": "0.0.0",
  "private": true,
  "description": "A dependency-free toolkit for opencode: night-shift session supervisor + local usage console",
  "license": "MIT",
  "scripts": {
    "test": "npm --prefix packages/night-shift test",
    "test:dashboard": "node --test dashboard/test/cleanup.test.cjs"
  }
}

{
  "name": "opencode-night-shift",
  "version": "0.2.0",
  "description": "Shift-based session supervisor for opencode: auto-continues multiple sessions until an end time, with real-time anchors, busy-awareness, completion detection and zero dependencies.",
  "type": "module",
  "main": "src/night-shift.js",
  "exports": {
    ".": "./src/night-shift.js"
  },
  "files": [
    "src",
    "assets"
  ],
  "scripts": {
    "test": "node --test"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "night-shift",
    "shift",
    "auto-continue",
    "session-supervisor",
    "long-running",
    "overnight",
    "agent"
  ],
  "license": "MIT",
  "engines": {
    "node": ">=20"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/kujiangmudao/opencode-console.git"
  },
  "bugs": {
    "url": "https://github.com/kujiangmudao/opencode-console/issues"
  },
  "homepage": "https://github.com/kujiangmudao/opencode-console/tree/main/packages/night-shift#readme"
}
